"""Warehouse fulfilment endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.fulfilment_service import FulfilmentService
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_non_negative_int, require_positive_int, require_str)


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            slip = self._service.packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)
        return Response(200, {
            "order_id": slip.order_id,
            "customer_name": slip.customer_name,
            "lines": [{"sku": line.sku, "name": line.name, "quantity": line.quantity}
                      for line in slip.lines],
        })

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            on_hand = self._service.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, {"sku": sku, "on_hand": on_hand})

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            limit = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        products = self._service.low_stock(limit)
        return Response(200, {"products": [{"sku": p.sku, "name": p.name, "on_hand": p.on_hand}
                                           for p in products]})

def _order(shop, items):
    return shop.orders.handle_create({"customer_id": "c1", "items": items}).body["order_id"]


def test_packing_slip(shop):
    oid = _order(shop, [{"sku": "PEN", "quantity": 2}, {"sku": "BOOK", "quantity": 1}])
    r = shop.fulfilment.handle_packing_slip(oid)
    assert r.status == 200
    assert r.body == {"order_id": oid, "customer_name": "Ada", "lines": [
        {"sku": "PEN", "name": "Pen", "quantity": 2}, {"sku": "BOOK", "name": "Book", "quantity": 1}]}


def test_packing_slip_unknown(shop):
    r = shop.fulfilment.handle_packing_slip("nope")
    assert (r.status, r.body) == (404, {"error": "order not found"})


def test_packing_slip_cancelled(shop):
    oid = _order(shop, [{"sku": "PEN", "quantity": 1}])
    shop.orders.handle_cancel(oid)
    r = shop.fulfilment.handle_packing_slip(oid)
    assert r.status == 409 and "error" in r.body


def test_low_stock_sorted_and_strict(shop):
    shop.catalog.handle_add_product({"sku": "ABC", "name": "Abc", "unit_price_cents": 1, "on_hand": 5})
    r = shop.fulfilment.handle_low_stock(100)
    assert r.status == 200
    assert r.body["products"] == [
        {"sku": "ABC", "name": "Abc", "on_hand": 5}, {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
        {"sku": "BOOK", "name": "Book", "on_hand": 50}]
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}


def test_restock_adds_stock_and_is_orderable(shop):
    r = shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 10})
    assert (r.status, r.body) == (200, {"sku": "LAMP", "on_hand": 15})
    assert shop.catalog.handle_get("LAMP").body["on_hand"] == 15
    o = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "LAMP", "quantity": 15}]})
    assert o.status == 201


def test_restock_unknown_product(shop):
    r = shop.fulfilment.handle_restock({"sku": "NOPE", "quantity": 1})
    assert (r.status, r.body) == (404, {"error": "product not found"})


def test_restock_invalid_requests_change_nothing(shop):
    for req in ({}, {"sku": "", "quantity": 1}, {"sku": 3, "quantity": 1}, {"sku": "PEN"},
                {"sku": "PEN", "quantity": 0}, {"sku": "PEN", "quantity": -2},
                {"sku": "PEN", "quantity": True}, {"sku": "PEN", "quantity": "5"},
                {"sku": "NOPE", "quantity": 0}):
        r = shop.fulfilment.handle_restock(req)
        assert r.status == 400 and "error" in r.body
    assert shop.catalog.handle_get("PEN").body["on_hand"] == 100


def test_low_stock_invalid_threshold(shop):
    for bad in (-1, True, "5", 1.5, None):
        r = shop.fulfilment.handle_low_stock(bad)
        assert r.status == 400 and "error" in r.body
